          (.set-cmdindent (g ed ccline) (i32 (+ (g ed msg-col) (i32 (* (i32 (- (g ed msg-row) (g ed cmdline-row))) (g ed cmdline-width))))))
          (when-not (== (.cmdfirstc (g ed ccline)) (e NUL))
            (.set-cmdindent (g ed ccline) (i32 (dec (.cmdindent (g ed ccline)))))
            nil))
      (let [i (.cmdindent (g ed ccline))]
        (loop [i i]
          (when (> i 0)
            (msg-putchar ed 32)
            (let [i (i32 (dec i))]
              (recur i))))))))

