;; C: mb_adjustpos
(defn mb-adjustpos [^Editor ed ^S_file_buffer buf ^T_pos_T lp]
  (when (or (> (.col lp) 0) (> (.coladd lp) 1))
    (let [^BytePtr p (ml-get-buf ed buf (.lnum lp) false)]
      (if (or (== (.ub p) (e NUL)) (< (long (ml-get-buf-len ed buf (.lnum lp))) (.col lp)))
        (.set-col lp 0)
        (let [t1 (long (utf-head-off ed p (.add p (.col lp))))]
          (.set-col lp (i32 (- (.col lp) t1)))))
      (when (and (== (.coladd lp) 1) (not (== (.ub p (.col lp)) (e TAB))) (vim-isprintc? ed (long (utf-ptr2char ed (.add p (.col lp))))) (> (long (ptr2cells ed (.add p (.col lp)))) 1))
        (.set-coladd lp 0)
        nil))))

;; C: check_cursor_col_win
(defn check-cursor-col-win [^Editor ed ^S_window_S win]
  (let [^ints cs (int-array 1)
        ^ints ce (int-array 1)
        oldcol (.col ^T_pos_T (.-w-cursor win))
        oldcoladd (i32 (+ (.col ^T_pos_T (.-w-cursor win)) (.coladd ^T_pos_T (.-w-cursor win))))
        cur-ve-flags (long (get-ve-flags ed))
        len (long (ml-get-buf-len ed (.w-buffer win) (.lnum ^T_pos_T (.-w-cursor win))))]
    (if (== len 0)
      (.set-col ^T_pos_T (.-w-cursor win) 0)
      (if (>= (.col ^T_pos_T (.-w-cursor win)) len)
        (if (or (not (zero? (bit-and (g ed State) (e MODE_INSERT)))) (not (zero? (g ed restart-edit))) (and (not (zero? (g ed VIsual-active))) (not (== (.ub ^BytePtr (aget (g ed p-sel) 0)) 111))) (not (zero? (bit-and cur-ve-flags (e VE_ONEMORE)))) (not (zero? (long (virtual-active ed)))))
          (.set-col ^T_pos_T (.-w-cursor win) len)
          (do (.set-col ^T_pos_T (.-w-cursor win) (i32 (- len 1)))
              (mb-adjustpos ed (.w-buffer win) (.-w-cursor win))))
        (when (< (.col ^T_pos_T (.-w-cursor win)) 0)
          (.set-col ^T_pos_T (.-w-cursor win) 0))))
    (if (== oldcol (e MAXCOL))
      (do (.set-coladd ^T_pos_T (.-w-cursor win) 0)
          nil)
      (when (== cur-ve-flags (e VE_ALL))
        (if (> oldcoladd (.col ^T_pos_T (.-w-cursor win)))
          (do (.set-coladd ^T_pos_T (.-w-cursor win) (i32 (- oldcoladd (.col ^T_pos_T (.-w-cursor win)))))
              (when (< (i32 (+ (.col ^T_pos_T (.-w-cursor win)) 1)) len)
                (getvcol ed win (.-w-cursor win) (IntPtr. cs 0) nil (IntPtr. ce 0) 0)
                (when (> (.coladd ^T_pos_T (.-w-cursor win)) (i32 (- (long (aget ce 0)) (long (aget cs 0)))))
                  (.set-coladd ^T_pos_T (.-w-cursor win) (i32 (- (long (aget ce 0)) (long (aget cs 0)))))
                  nil)))
          (do (.set-coladd ^T_pos_T (.-w-cursor win) 0)
              nil))))))

;; C: check_cursor_col
