  (loop [st 0
         ^S_exarg eap eap
         ^Ptr errormsg errormsg
         silent silent
         address-count 0
         lnum 0
         need-check-cursor false
         ret false]
    (case st
      0
        (let [address-count 1
              need-check-cursor false
              ret false]
          (recur 1 eap errormsg silent address-count lnum need-check-cursor ret))
      1
        (do (.set-line1 eap (.line2 eap))
            (.set-line2 eap (long (default-address ed eap)))
            (aset ^objects (.-cmd eap) 0 (skipwhite ed (aget ^objects (.-cmd eap) 0)))
            (let [t1 address-count
                  address-count (i32 (inc address-count))
                  lnum (long (get-address ed eap (Ptr. ^objects (.-cmd eap) 0) (.addr-type eap) false silent (== (.addr-count eap) 0) t1))]
              (if (nil? (aget ^objects (.-cmd eap) 0))
                (recur 5 eap errormsg silent address-count lnum need-check-cursor ret)
                (if (== lnum (e LONG_MAX))
                  (if (== (.ub ^BytePtr (aget ^objects (.-cmd eap) 0)) 37)
                    (do (aset ^objects (.-cmd eap) 0 (.add ^BytePtr (aget ^objects (.-cmd eap) 0) 1))
                        (case (case (.addr-type eap) (0 10) 0 1 1 9 2 -1)
                          0
                            (do (.set-line1 eap 1)
                                (.set-line2 eap (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))))
                                (recur 2 eap errormsg silent address-count lnum need-check-cursor ret))
                          1
                            (do (.put errormsg (gettext_ ed (BytePtr. (g ed e-invalid-range) 0)))
                                (recur 5 eap errormsg silent address-count lnum need-check-cursor ret))
                          2
                            (do (.put errormsg (gettext_ ed (BytePtr. (g ed e-invalid-range) 0)))
